1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.DayOfWeek;
4	import java.time.LocalDate;
5	import java.util.Set;
6	
7	/**
8	 * Rolls a registration date forward onto a business day. A Saturday, Sunday or listed
9	 * public holiday is rolled forward to the next non-holiday weekday; a plain weekday is
10	 * returned unchanged. Shared by {@link BuildOwner} (which stores the adjusted date, so
11	 * every value derived from it — such as the membership number's year segment — uses the
12	 * business day) and {@link CheckOwnerDailyLimit} (which counts owners per adjusted
13	 * business day).
14	 */
15	final class BusinessDay {
16	
17	    /** Fixed public holidays the business-day roll skips. */
18	    private static final Set<LocalDate> HOLIDAYS = Set.of(
19	            LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
20	            LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"), LocalDate.parse("2026-12-28"));
21	
22	    private BusinessDay() {
23	    }
24	
25	    /** Returns {@code date} if it is a non-holiday weekday, else the next business day. */
26	    static LocalDate adjust(LocalDate date) {
27	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY
28	                || HOLIDAYS.contains(date)) {
29	            date = date.plusDays(1);
30	        }
31	        return date;
32	    }
33	}
