1	package org.springframework.samples.petclinic.model;
2	
3	import java.time.LocalDate;
4	import java.time.temporal.ChronoUnit;
5	
6	/**
7	 * Derives an owner's numeric membership points.
8	 *
9	 * <p>Starts at 0; add 2 when an email is present; add 1 when {@code namesakeCount}
10	 * is 0; add 2 for a household of 3 or more; add 3 for tenure over 365 days.
11	 */
12	public final class MembershipPoints {
13	
14	    /** Household size, at or above which the household bonus applies. */
15	    public static final int HOUSEHOLD_SIZE = 3;
16	
17	    /** Tenure, in days, that must be exceeded to earn the tenure bonus. */
18	    public static final long TENURE_DAYS = 365;
19	
20	    private MembershipPoints() {
21	    }
22	
23	    /** The membership points for the given owner. */
24	    public static int of(Owner owner) {
25	        int points = 0;
26	        if (owner.getEmail() != null && !owner.getEmail().isEmpty()) {
27	            points += 2;
28	        }
29	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
30	            points += 1;
31	        }
32	        if (owner.getHouseholdSize() != null && owner.getHouseholdSize() >= HOUSEHOLD_SIZE) {
33	            points += 2;
34	        }
35	        if (hasTenure(owner)) {
36	            points += 3;
37	        }
38	        return points;
39	    }
40	
41	    /** Whether the owner's tenure exceeds {@link #TENURE_DAYS} days. */
42	    private static boolean hasTenure(Owner owner) {
43	        LocalDate registrationDate = owner.getRegistrationDate();
44	        if (registrationDate == null) {
45	            return false;
46	        }
47	        return ChronoUnit.DAYS.between(registrationDate, LocalDate.now()) > TENURE_DAYS;
48	    }
49	}
