6	/**
7	 * Derives an owner's age band from their {@code birthDate}, measured at the moment of
8	 * registration ({@code registrationDate}): {@link #MINOR} when under 18, {@link #ADULT}
9	 * from 18 to 64, {@link #SENIOR} at 65 or older.
10	 *
11	 * <p>Null when the owner has no birthDate. When the registrationDate is absent the age is
12	 * measured against the current date instead.
13	 */
14	public final class AgeBand {
15	
16	    /** Under 18 at registration. */
17	    public static final String MINOR = "MINOR";
18	
19	    /** 18 to 64 (inclusive) at registration. */
20	    public static final String ADULT = "ADULT";
21	
22	    /** 65 or older at registration. */
23	    public static final String SENIOR = "SENIOR";
24	
25	    private AgeBand() {
26	    }
27	
28	    /** The owner's age band, or {@code null} when no birthDate was supplied. */
29	    public static String of(Owner owner) {
30	        LocalDate birthDate = owner.getBirthDate();
31	        if (birthDate == null) {
32	            return null;
33	        }
34	        LocalDate asOf = owner.getRegistrationDate();
35	        if (asOf == null) {
36	            asOf = LocalDate.now();
37	        }
38	        int age = Period.between(birthDate, asOf).getYears();
39	        if (age < 18) {
40	            return MINOR;
41	        }
42	        if (age < 65) {
43	            return ADULT;
44	        }
45	        return SENIOR;
46	    }
47	}
